// One row per source. type: rss | gdelt | worldbank | wbprojects | gnews | newsdata | newsapi | eventregistry
// filter:true = keep only items whose title or link matches KEYWORD_FILTER (for regional/global feeds).
const cfg = $('Config').first().json;
const S = [];
const add = (group, name, lang, url, o = {}) => S.push({ group, name, lang, url, type: o.type || 'rss', filter: !!o.filter });

// Jordan · English (verified 10 Nov 2026)
add('1 Jordan · English', 'Jordan News', 'en', 'https://www.jordannews.jo/rss');
add('1 Jordan · English', 'Ammon News EN · Jordan', 'en', 'https://en.ammonnews.net/rss.php?type=news&id=2');
add('1 Jordan · English', 'Ammon News EN · Business', 'en', 'https://en.ammonnews.net/rss.php?type=news&id=4');
