// Jordan · Arabic (verified 10 Nov 2026)
add('2 Jordan · Arabic', 'Ammon AR · Jordan news', 'ar', 'https://www.ammonnews.net/rss.php?type=news&id=50');
add('2 Jordan · Arabic', 'Ammon AR · Economy', 'ar', 'https://www.ammonnews.net/rss.php?type=news&id=3');
