add('2 Jordan · Arabic', 'Saraya · Parliament', 'ar', 'https://www.sarayanews.com/rss.php?type=news&id=147');
add('2 Jordan · Arabic', 'Saraya · City talk', 'ar', 'https://www.sarayanews.com/rss.php?type=news&id=13');
