add('2 Jordan · Arabic', 'Jo24', 'ar', 'https://jo24.net/rss.xml');
add('2 Jordan · Arabic', 'Hala Akhbar', 'ar', 'https://www.hala.jo/feed/');
add('2 Jordan · Arabic', 'Sawaleif', 'ar', 'https://sawaleif.com/feed/');
add('2 Jordan · Arabic', '7iber', 'ar', 'https://www.7iber.com/feed/');
add('2 Jordan · Arabic', 'Roya News (Atom)', 'ar', 'https://royanews.tv/rss');
add('2 Jordan · Arabic', 'Al Jazeera Arabic (regional, filtered)', 'ar', 'https://www.aljazeera.net/aljazeerarss/a7c186be-1baa-4bd4-9d80-a84db769f779/73d0e1b4-532f-45ef-b135-bfdff8b8cab9', { filter: true });

// Jordan · official and research
add('3 Jordan · official', 'Central Bank of Jordan AR', 'ar', 'https://www.cbj.gov.jo/RSSFeeds/RSSNewsAR.aspx');
add('3 Jordan · official', 'Central Bank of Jordan EN (challenge page seen 10 Nov)', 'en', 'https://www.cbj.gov.jo/RSSFeeds/RSSNewsEN.aspx');
add('3 Jordan · official', 'Department of Statistics EN', 'en', 'https://dosweb.dos.gov.jo/feed/');
add('3 Jordan · official', 'Department of Statistics AR', 'ar', 'https://dosweb.dos.gov.jo/ar/feed/');
add('3 Jordan · official', 'Arab Barometer · Jordan', 'en', 'https://www.arabbarometer.org/countries/jordan/feed/');
add('3 Jordan · official', 'EcoPeace Middle East', 'en', 'https://ecopeaceme.org/feed/');

// Jordan · blocked to crawlers on 10 Nov 2026 (kept so the summary documents it)
add('4 Jordan · blocked (expected to fail)', 'Jordan Times', 'en', 'https://jordantimes.com/rss.xml');
add('4 Jordan · blocked (expected to fail)', 'Al Rai', 'ar', 'https://alrai.com/rss');
add('4 Jordan · blocked (expected to fail)', 'Al Ghad', 'ar', 'https://alghad.com/feed/');
add('4 Jordan · blocked (expected to fail)', 'Al-Mamlaka TV', 'ar', 'https://www.almamlakatv.com/rss');
add('4 Jordan · blocked (expected to fail)', 'Petra (state news agency) EN', 'en', 'https://petra.gov.jo/rss.aspx?lang=en');
add('4 Jordan · blocked (expected to fail)', 'Ad-Dustour', 'ar', 'https://www.addustour.com/rss');

// Donors, UN and development media (verified 10 Nov 2026)
add('5 Donors and development media', 'BMZ press', 'en', 'https://www.bmz.de/en/feed.rss');
add('5 Donors and development media', 'ReliefWeb · updates mentioning Jordan', 'en', 'https://reliefweb.int/updates/rss.xml?search=Jordan');
add('5 Donors and development media', 'ReliefWeb · Jordan country feed', 'en', 'https://reliefweb.int/country/jor/rss.xml');
add('5 Donors and development media', 'EIB press (filtered)', 'en', 'https://www.eib.org/en/press/all/index.rss', { filter: true });
add('5 Donors and development media', 'EIB loans signed (filtered)', 'en', 'https://www.eib.org/en/projects/loans/all/index.rss', { filter: true });
add('5 Donors and development media', 'EIB pipelines (filtered)', 'en', 'https://www.eib.org/en/projects/pipelines/index.rss', { filter: true });
add('5 Donors and development media', 'D+C Development and Cooperation (filtered)', 'en', 'https://www.dandc.eu/en/rss.xml', { filter: true });
add('5 Donors and development media', 'The New Humanitarian (filtered)', 'en', 'https://www.thenewhumanitarian.org/rss/all.xml', { filter: true });
add('5 Donors and development media', 'Al-Monitor (filtered)', 'en', 'https://www.al-monitor.com/rss', { filter: true });
add('5 Donors and development media', 'Devex (filtered, paywalled text)', 'en', 'https://www.devex.com/news/feed.rss', { filter: true });
add('5 Donors and development media', 'Qantara (challenge page seen 10 Nov)', 'en', 'https://qantara.de/en/rss.xml', { filter: true });

// Keyless discovery feeds and APIs
add('6 Discovery · no key', 'GDELT Global Article List feed (filtered)', 'mixed', 'https://data.gdeltproject.org/gdeltv3/gal/feed.rss', { filter: true });
add('6 Discovery · no key', 'GDELT DOC 2.0 · Jordanian Arabic press, 2 days', 'ar', 'https://api.gdeltproject.org/api/v2/doc/doc?query=sourcecountry:JO%20sourcelang:ara&mode=artlist&maxrecords=250&format=json&timespan=2d&sort=datedesc', { type: 'gdelt' });
add('6 Discovery · no key', 'World Bank news · Jordan', 'mixed', 'https://search.worldbank.org/api/v2/news?format=json&countrycode_exact=JO&rows=50', { type: 'worldbank' });
add('6 Discovery · no key', 'World Bank projects · Jordan', 'en', 'https://search.worldbank.org/api/v2/projects?format=json&countrycode_exact=JO&rows=50', { type: 'wbprojects' });
add('7 Alerts · personal-use terms, check only', 'Google News RSS · "Jordan GIZ"', 'en', 'https://news.google.com/rss/search?q=Jordan+GIZ&hl=en-US&gl=US&ceid=US:en');
add('7 Alerts · personal-use terms, check only', 'Google News RSS · Jordan donors', 'en', 'https://news.google.com/rss/search?q=Jordan+(%22World+Bank%22+OR+KfW+OR+BMZ+OR+UNHCR+OR+%22European+Union%22)&hl=en-US&gl=US&ceid=US:en');

// APIs that need only a self-service key (added when the key is filled in the Config node)
if (cfg.GNEWS_KEY) {
  add('8 API · free key', 'GNews EN · q=Jordan', 'en', `https://gnews.io/api/v4/search?q=Jordan&lang=en&max=10&sortby=publishedAt&apikey=${cfg.GNEWS_KEY}`, { type: 'gnews' });
  add('8 API · free key', 'GNews AR · q=الأردن', 'ar', `https://gnews.io/api/v4/search?q=${encodeURIComponent('الأردن')}&lang=ar&max=10&sortby=publishedAt&apikey=${cfg.GNEWS_KEY}`, { type: 'gnews' });
}
if (cfg.NEWSDATA_KEY) add('8 API · free key', 'NewsData.io · country=jo', 'mixed', `https://newsdata.io/api/1/latest?apikey=${cfg.NEWSDATA_KEY}&country=jo`, { type: 'newsdata' });
if (cfg.NEWSAPI_KEY) add('8 API · free key', 'NewsAPI.org · q=Jordan (24 h delay on free tier)', 'en', `https://newsapi.org/v2/everything?q=Jordan&language=en&sortBy=publishedAt&pageSize=50&apiKey=${cfg.NEWSAPI_KEY}`, { type: 'newsapi' });
if (cfg.EVENTREGISTRY_KEY) add('8 API · free key', 'Event Registry · Jordan sources', 'mixed', `https://eventregistry.org/api/v1/article/getArticles?apiKey=${cfg.EVENTREGISTRY_KEY}&resultType=articles&sourceLocationUri=${encodeURIComponent('http://en.wikipedia.org/wiki/Jordan')}&articlesSortBy=date&articlesCount=50&lang=eng,ara`, { type: 'eventregistry' });

// A second GDELT query last, so the two GDELT calls are minutes apart (GDELT allows one call per 5 seconds).
add('6 Discovery · no key', 'GDELT DOC 2.0 · donors in Jordan, English, 3 days', 'en', 'https://api.gdeltproject.org/api/v2/doc/doc?query=Jordan%20(GIZ%20OR%20KfW%20OR%20BMZ%20OR%20%22World%20Bank%22%20OR%20UNHCR%20OR%20UNICEF%20OR%20UNDP%20OR%20%22European%20Union%22)%20sourcelang:eng&mode=artlist&maxrecords=100&format=json&timespan=3d&sort=datedesc', { type: 'gdelt' });

return S.map(s => ({ json: s }));

// Runs once per source (the loop passes one source at a time). Turns whatever came back into one row per article.
const src = $('Loop Over Items').first().json;
const cfg = $('Config').first().json;
const re = new RegExp(cfg.KEYWORD_FILTER || 'Jordan|Amman|الأردن|عمان', 'i');
const base = { group: src.group, source: src.name, lang: src.lang, type: src.type, feedUrl: src.url.replace(/(apikey|apiKey)=[^&]+/i, '$1=***') };
const out = [];
const toIso = (d) => {
  if (!d) return null;
  if (/^\d{8}T\d{6}Z$/.test(d)) return `${d.slice(0,4)}-${d.slice(4,6)}-${d.slice(6,8)}T${d.slice(9,11)}:${d.slice(11,13)}:${d.slice(13,15)}Z`;
  const t = Date.parse(String(d).replace(' ', 'T'));
  return isNaN(t) ? String(d) : new Date(t).toISOString();
};
const push = (title, link, date, extra) => {
  if (src.filter && !re.test(`${title || ''} ${link || ''}`)) return;
  out.push({ json: Object.assign({}, base, { title: title || null, link: link || null, date: toIso(date) }, extra || {}) });
};
const fail = (msg) => out.push({ json: Object.assign({}, base, { error: String(msg).slice(0, 300) }) });

for (const it of $input.all()) {
  const j = it.json || {};
  if (j.error) { fail(typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error))); continue; }
  if (j.status === 'error' || j.errors) { fail(JSON.stringify(j.errors || j.results || j.message || j).slice(0, 300)); continue; }
  switch (src.type) {
    case 'rss':
      if (j.title || j.link) push(j.title, j.link, j.isoDate || j.pubDate || j.published);
      break;
    case 'gdelt':
      if (Array.isArray(j.articles)) for (const a of j.articles) push(a.title, a.url, a.seendate, { domain: a.domain, country: a.sourcecountry, articleLang: a.language });
      else fail('GDELT returned no article list: ' + String(j.data || JSON.stringify(j)).slice(0, 200));
      break;
    case 'worldbank': {
      const docs = j.documents || {};
      for (const k of Object.keys(docs)) { if (k === 'facets') continue; const d = docs[k]; push((d.title && d.title['cdata!']) || d.title, d.url, d.lnchdt, { articleLang: d.lang }); }
      break;
    }
    case 'wbprojects': {
      const ps = j.projects || {};
      for (const k of Object.keys(ps)) { const p = ps[k]; push(p.project_name, p.url, p.boardapprovaldate, { status: p.status }); }
      break;
    }
    case 'gnews':
    case 'newsapi':
      for (const a of (j.articles || [])) push(a.title, a.url, a.publishedAt, { domain: a.source && a.source.name });
      break;
    case 'newsdata':
      for (const a of (j.results || [])) push(a.title, a.link, a.pubDate, { domain: a.source_id, articleLang: a.language });
      break;
    case 'eventregistry':
      for (const a of ((j.articles && j.articles.results) || [])) push(a.title, a.url, a.dateTime || a.date, { domain: a.source && a.source.title, articleLang: a.lang });
      break;
  }
}
if (!out.length) out.push({ json: Object.assign({}, base, { empty: true }) });
return out;

// One row per source: status, item counts, newest and oldest dates, a sample title. First row is the total.
const hours = Number($('Config').first().json.HOURS_BACK) || 48;
const since = Date.now() - hours * 3600e3;
const by = {};
for (const it of $input.all()) {
  const r = it.json;
  if (!by[r.source]) by[r.source] = { group: r.group, source: r.source, lang: r.lang, type: r.type, status: 'EMPTY', items: 0, ['last' + hours + 'h']: 0, newest: null, oldest: null, sample: null, error: null, feedUrl: r.feedUrl };
  const s = by[r.source];
  if (r.error) { s.error = r.error; s.status = 'ERROR'; continue; }
  if (r.empty) continue;
  s.items++; s.status = 'OK';
  if (!s.sample) s.sample = r.title;
  const t = Date.parse(r.date);
  if (!isNaN(t)) {
    if (t >= since) s['last' + hours + 'h']++;
    if (!s.newest || t > Date.parse(s.newest)) s.newest = new Date(t).toISOString();
    if (!s.oldest || t < Date.parse(s.oldest)) s.oldest = new Date(t).toISOString();
  }
}
const list = Object.values(by).sort((a, b) => a.group.localeCompare(b.group) || a.source.localeCompare(b.source));
const n = (st) => list.filter(s => s.status === st).length;
const total = { group: '', source: 'TOTAL', status: `${n('OK')} OK · ${n('EMPTY')} empty · ${n('ERROR')} error`, items: list.reduce((a, s) => a + s.items, 0), ['last' + hours + 'h']: list.reduce((a, s) => a + s['last' + hours + 'h'], 0) };
return [total, ...list].map(j => ({ json: j }));

// Every article fetched, newest first, so the actual coverage can be read item by item.
return $input.all()
  .filter(i => !i.json.error && !i.json.empty)
  .sort((a, b) => (Date.parse(b.json.date) || 0) - (Date.parse(a.json.date) || 0));

// Runs once per article (or once per failed/empty feed).
// Pull the feed name/url from the Loop item that produced this article.
const src = $('Loop Over Items1').item.json;
const a = $input.item.json;
const err = a.error;

let status = 'ok';
if (err) status = 'failed';
else if (!a.link && !a.title) status = 'empty';

return {
  json: {
    index: src.index,
    name: src.name,
    url: src.url,
    status,
    error: err ? (typeof err === 'string' ? err : (err.message ?? JSON.stringify(err))) : '',
  },
};

// Collapse the per-article rows coming out of the loop into one row per source.
const rows = new Map();

for (const { json } of $input.all()) {
  if (!rows.has(json.index)) {
    rows.set(json.index, {
      index: json.index,
      name: json.name,
      url: json.url,
      status: json.status,
      articles: 0,
      error: json.error || '',
    });
  }
  const row = rows.get(json.index);
  if (json.status === 'ok') row.articles += 1;
  if (json.status === 'failed') {
    row.status = 'failed';
    row.error = json.error || row.error;
  }
}

// Safety net: any source that never produced a row at all
for (const { json } of $('Code in JavaScript').all()) {
  if (!rows.has(json.index)) {
    rows.set(json.index, {
      index: json.index,
      name: json.name,
      url: json.url,
      status: 'failed',
      articles: 0,
      error: 'No output from RSS Read',
    });
  }
}

const list = [...rows.values()].sort((a, b) => a.index - b.index);
const ok = list.filter(r => r.status === 'ok').length;
const failed = list.filter(r => r.status === 'failed').length;
const empty = list.filter(r => r.status === 'empty').length;

return list.map(r => ({
  json: { ...r, summary: `${ok} ok / ${failed} failed / ${empty} empty of ${list.length}` },
}));

// Flattens the BMZ portal pages into one row per German-funded activity in Jordan, flags GIZ and KfW, maps DAC codes to clusters.
const cfg = $('Donor Config').first().json;
const days = Number(cfg.DAYS_RECENT) || 90, now = Date.now(), span = days * 864e5;
const STATUS = { '1': 'pipeline', '2': 'implementation', '3': 'finalisation', '4': 'closed', '5': 'cancelled', '6': 'suspended' };
const RULES = [
  [/^(16020|16070)/, 'Employment & TVET'], [/^(15190|16010|43030|7[234]\d{3})/, 'Displacement & Social Cohesion'],
  [/^(32130)/, 'Private Sector & Trade'], [/^(43010)/, 'Cross-cutting'],
  [/^(14|23|41)/, 'Water & Energy'], [/^(11|16)/, 'Employment & TVET'], [/^(15)/, 'Good Governance'],
  [/^(24|25|32|33)/, 'Private Sector & Trade'], [/^(31)/, 'Private Sector & Trade']
];
const cluster = (codes) => { for (const c of codes) for (const [re, name] of RULES) if (re.test(String(c))) return name; return codes.length ? 'Other' : 'Unspecified'; };
const seen = new Set(), rows = [];
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.error) continue;
  for (const a of (j.data || [])) {
    if (!a || seen.has(a.id)) continue; seen.add(a.id);
    const orgs = a.participating_organisations || [];
    const refs = orgs.map(o => o.ref || '');
    const names = (role) => orgs.filter(o => o.role === role).map(o => (o.narrative && (o.narrative.en || o.narrative.de)) || o.ref).filter(Boolean);
    const sectors = (a.sectors || []).map(String);
    const start = a.start_actual || a.start_planned || null, end = a.end_actual || a.end_planned || null;
    const t0 = Date.parse(start), t1 = Date.parse(end), tu = Date.parse(a.last_updated_datetime);
    rows.push({ json: {
      id: a.id, title: (a.title && (a.title.en || a.title.de)) || '', title_language: (a.title && a.title.en) ? 'en' : 'de',
      status: STATUS[String(a.status)] || String(a.status), is_giz: refs.includes('XM-DAC-5-52'), is_kfw: refs.includes('XM-DAC-5-2'),
      implementers: names('4').join('; '), extending: names('3').join('; '),
      start, end, volume_eur: a.volume || null, budget_eur: a.budget || null,
      dac_sectors: sectors.join('; '), cluster: cluster(sectors),
      recently_started: !isNaN(t0) && now - t0 <= span && t0 <= now, ending_soon: !isNaN(t1) && t1 >= now && t1 - now <= span,
      updated_recently: !isNaN(tu) && now - tu <= span, last_updated: a.last_updated_datetime || null,
      documents: (a.document_links || []).length, description: ((a.description && (a.description.en || a.description.de)) || '').slice(0, 400),
      link: 'https://www.transparenzportal.bund.de/en/activities/' + encodeURIComponent(a.id)
    }});
  }
}
const order = { implementation: 0, finalisation: 1, pipeline: 2, closed: 3 };
rows.sort((a, b) => (b.json.is_giz - a.json.is_giz) || ((order[a.json.status] ?? 9) - (order[b.json.status] ?? 9)) || String(a.json.end).localeCompare(String(b.json.end)));
const n = (f) => rows.filter(f).length;
const summary = { json: { id: 'SUMMARY', title: `German cooperation in Jordan: ${rows.length} activities · GIZ ${n(r => r.json.is_giz)} (${n(r => r.json.is_giz && r.json.status === 'implementation')} in implementation) · KfW ${n(r => r.json.is_kfw)} · ending within ${days} days: ${n(r => r.json.ending_soon)} · started within ${days} days: ${n(r => r.json.recently_started)}`, pages_with_errors: $input.all().filter(i => i.json && i.json.error).length } };
return [summary, ...rows];

// Structured donor sources that need no key (ReliefWeb's API is added once an approved appname is in Donor Config).
const cfg = $('Donor Config').first().json;
const S = [
  { name: 'World Bank · projects in Jordan', type: 'wb_projects', format: 'json', url: 'https://search.worldbank.org/api/v2/projects?format=json&countrycode_exact=JO&rows=200&srt=boardapprovaldate&order=desc' },
  { name: 'World Bank · documents on Jordan since 2026-01-01', type: 'wb_docs', format: 'json', url: 'https://search.worldbank.org/api/v3/wds?format=json&count_exact=Jordan&rows=100&strdate=2026-01-01&srt=docdt&order=desc' },
  { name: 'World Bank · news on Jordan', type: 'wb_news', format: 'json', url: 'https://search.worldbank.org/api/v2/news?format=json&countrycode_exact=JO&rows=30&srt=lnchdt&order=desc' },
  { name: 'OCHA FTS · 2026 humanitarian flows to Jordan', type: 'fts', format: 'json', url: 'https://api.hpc.tools/v1/public/fts/flow?countryISO3=JOR&year=2026' },
  { name: 'AFD · projects in Jordan', type: 'afd', format: 'json', url: 'https://opendata.afd.fr/api/explore/v2.1/catalog/datasets/les-projets-de-l-afd/records?where=recipient_country_code%3D%22JO%22&limit=100' },
  { name: 'FCDO DevTracker · Jordan projects', type: 'fcdo', format: 'text', url: 'https://devtracker.fcdo.gov.uk/countries/JO/projects' }
];
if (cfg.RELIEFWEB_APPNAME) S.push({ name: 'ReliefWeb API · reports on Jordan', type: 'reliefweb', format: 'json', url: `https://api.reliefweb.int/v1/reports?appname=${encodeURIComponent(cfg.RELIEFWEB_APPNAME)}&filter[field]=primary_country.iso3&filter[value]=jor&sort[]=date:desc&limit=50&fields[include][]=title&fields[include][]=date.created&fields[include][]=source.name&fields[include][]=url_alias&fields[include][]=format.name` });
return S.map(s => ({ json: s }));

// One row per project, document, flow or report, newest first. Output item i of the HTTP node corresponds to source i.
const srcs = $('Donor API sources').all().map(i => i.json);
const days = Number($('Donor Config').first().json.DAYS_RECENT) || 90, now = Date.now();
const num = (v) => { if (v == null) return null; const n = Number(String(v).replace(/[^0-9.-]/g, '')); return isNaN(n) ? null : n; };
const txt = (v) => (v && typeof v === 'object') ? (v['cdata!'] || v._ || JSON.stringify(v)) : (v == null ? null : String(v));
const out = [];
const push = (src, o) => out.push({ json: Object.assign({ donor_source: src.name, type: src.type }, o) });
$input.all().forEach((it, i) => {
  const src = srcs[i] || { name: 'unknown', type: 'unknown' };
  const j = it.json || {};
  if (j.error) { push(src, { error: typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error)).slice(0, 300) }); return; }
  switch (src.type) {
    case 'wb_projects':
      for (const p of Object.values(j.projects || {})) push(src, { title: p.project_name, status: p.status, date: p.boardapprovaldate, end: p.closingdate, amount_usd: num(p.totalamt || p.totalcommamt || p.curr_total_commitment), id: p.id, link: p.url || ('https://projects.worldbank.org/en/projects-operations/project-detail/' + p.id) });
      break;
    case 'wb_docs':
      for (const [k, d] of Object.entries(j.documents || {})) { if (k === 'facets') continue; push(src, { title: d.display_title || txt(d.title), date: d.docdt, doctype: d.docty, id: d.id, link: d.pdfurl || d.url }); }
      break;
    case 'wb_news':
      for (const [k, d] of Object.entries(j.documents || {})) { if (k === 'facets') continue; push(src, { title: txt(d.title), date: d.lnchdt, language: d.lang, id: d.id, link: d.url }); }
      break;
    case 'fts': {
