});
out.forEach(o => { const t = Date.parse(o.json.date); o.json.recent = !isNaN(t) && now - t <= days * 864e5; });
out.sort((a, b) => (Date.parse(b.json.date) || 0) - (Date.parse(a.json.date) || 0));
