// Parses one fetched feed (RSS or Atom, already converted to JSON) into one row per story, tagged with the donor it was found for.
const q = $('Donor news loop').first().json;
const cfg = $('Donor Config').first().json;
const jordan = new RegExp(cfg.JORDAN_FILTER || 'Jordan|الأردن', 'i');
const DONORS = [['GIZ', /\bGIZ\b|Deutsche Gesellschaft|German development|الوكالة الألمانية/i], ['KfW / BMZ', /\bKfW\b|\bBMZ\b|German government|German Embassy/i], ['World Bank', /World Bank|البنك الدولي/i], ['EU', /European Union|EU Delegation|Team Europe|European Commission|الاتحاد الأوروبي/i], ['UN agencies', /UNHCR|UNICEF|UNDP|WFP|\bILO\b|UNRWA|UN Women|UNFPA|\bOCHA\b/i], ['IMF', /\bIMF\b|صندوق النقد/i], ['United States', /State Department|USAID|\bDFC\b|U\.S\. (aid|assistance|embassy)/i], ['Arab and Islamic funds', /Arab Fund|Kuwait Fund|Saudi Fund|Islamic Development Bank|Abu Dhabi Fund/i], ['Other bilateral and IFIs', /\bJICA\b|\bAFD\b|\bEBRD\b|\bEIB\b|KOICA|Swiss|Netherlands|Norway|Canada/i]];
const arr = (v) => Array.isArray(v) ? v : (v == null ? [] : [v]);
const txt = (v) => v == null ? '' : (typeof v === 'string' ? v : (v._ || v['#text'] || (typeof v === 'object' && !Array.isArray(v) ? '' : String(v))));
const linkOf = (e) => { const l = e.link; if (!l) return txt(e.guid) || null; if (typeof l === 'string') return l; const ls = arr(l); const alt = ls.find(x => x && x.$ && (!x.$.rel || x.$.rel === 'alternate')) || ls[0]; return alt ? (alt.$ ? alt.$.href : txt(alt)) : null; };
const base = { feed: q.name, donor_query: q.donor };
const out = [];
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.error) { out.push({ json: Object.assign({}, base, { error: typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error)).slice(0, 300) }) }); continue; }
  let entries = [];
  if (j.rss && j.rss.channel) entries = arr(j.rss.channel.item);
  else if (j.feed) entries = arr(j.feed.entry);
  else if (j['rdf:RDF']) entries = arr(j['rdf:RDF'].item);
  else if (j.data && /<html/i.test(String(j.data))) { out.push({ json: Object.assign({}, base, { error: 'HTML page instead of a feed (challenge or block)' }) }); continue; }
  for (const e of entries) {
    let title = txt(e.title).trim(); const link = linkOf(e); const date = e.pubDate || e['dc:date'] || e.published || e.updated || e.date || null;
    let publisher = txt(e.source) || (e.source && e.source.$ && e.source.$.url) || '';
    const m = title.match(/^(.*)\s[-–]\s([^-–]{2,60})$/); if (m && publisher && m[2].trim() === publisher.trim()) title = m[1].trim(); else if (m && !publisher && /news\.google\.com/.test(String(link))) { title = m[1].trim(); publisher = m[2].trim(); }
    if (q.filter && !jordan.test(title + ' ' + (link || ''))) continue;
    let donor = q.donor; if (donor === 'auto') { const hit = DONORS.find(([, re]) => re.test(title)); donor = hit ? hit[0] : 'unassigned'; }
    out.push({ json: Object.assign({}, base, { donor, publisher: publisher || (link ? String(link).replace(/^https?:\/\/(www\.)?/, '').split('/')[0] : ''), title, link, date: date ? new Date(Date.parse(date) || 0).toISOString() : null }) });
  }
  if (!entries.length) out.push({ json: Object.assign({}, base, { empty: true, fetched: 0 }) });
}
return out;

// Deduplicates the discovered donor stories across queries and lists them newest first; the first row summarises the feeds.
const rows = $input.all().map(i => i.json);
const errors = rows.filter(r => r.error), empties = rows.filter(r => r.empty);
const seen = new Map();
for (const r of rows) {
  if (r.error || r.empty || !r.title) continue;
  const key = r.title.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim().slice(0, 90);
  if (!seen.has(key)) seen.set(key, Object.assign({}, r, { also_found_for: [] }));
  else { const s = seen.get(key); if (r.donor && r.donor !== s.donor && !s.also_found_for.includes(r.donor)) s.also_found_for.push(r.donor); }
}
const list = [...seen.values()].map(r => Object.assign(r, { also_found_for: r.also_found_for.join('; ') })).sort((a, b) => (Date.parse(b.date) || 0) - (Date.parse(a.date) || 0));
const byDonor = {}; list.forEach(r => { byDonor[r.donor] = (byDonor[r.donor] || 0) + 1; });
return [{ json: { feed: 'SUMMARY', title: `${list.length} unique donor stories from ${new Set(rows.map(r => r.feed)).size} feeds · ${errors.length} feed errors · ${empties.length} empty`, by_donor: byDonor, errors: errors.map(e => e.feed + ': ' + e.error) } }, ...list.map(j => ({ json: j }))];

const input = $input.all().map(item => item.json);

// Handle common response wrappers.
const organizations = input.flatMap(item => {
  if (Array.isArray(item)) return item;
  if (Array.isArray(item.data)) return item.data;
  if (Array.isArray(item.data?.organizations))
    return item.data.organizations;
  if (Array.isArray(item.organizations))
    return item.organizations;
  return item.id && item.name ? [item] : [];
});

const terms = [
  "giz",
  "deutsche gesellschaft",
  "internationale zusammenarbeit",
  "german technical cooperation",
  "gtz"
];

return organizations
  .filter(org => {
    const text = [
      org.name,
      org.abbreviation,
      org.nativeName
    ].filter(Boolean).join(" ").toLowerCase();

    return terms.some(term => text.includes(term));
  })
  .map(org => ({
    json: {
      id: org.id,
      name: org.name,
      abbreviation: org.abbreviation ?? null,
      categories: org.categories ?? []
    }
  }));
